.timeline-card{margin-top:32px;padding:32px;background:#ffffffc7;border:1px solid var(--line)}.timeline-card h2{margin:4px 0 26px;font:400 25px var(--display)}.proses-timeline{display:flex;align-items:flex-start;overflow-x:auto;padding:8px 4px 14px}.proses-item{position:relative;flex:1 1 0;min-width:150px;padding:0 8px;color:var(--muted);text-align:center;text-decoration:none}.proses-item:before{content:"";position:absolute;z-index:0;top:22px;left:-50%;width:100%;height:2px;background:#d7e2e8}.proses-item:first-child:before{display:none}.proses-icon{position:relative;z-index:1;display:flex;align-items:center;justify-content:center;width:44px;height:44px;margin:0 auto 12px;border-radius:50%;background:#dfe6ea;color:#7c8a94;transition:.2s}.proses-icon svg{width:22px;height:22px}.proses-item:hover .proses-icon{transform:translateY(-2px);box-shadow:0 0 0 4px rgba(165,126,44,.14)}.proses-body b{display:block;margin-bottom:5px;font:400 14px var(--display);color:var(--text)}.proses-body small{display:block;font-size:11px;line-height:1.5}.proses-item.done:before,.proses-item.current:before{background:#4c8791}.proses-item.done .proses-icon{background:#4c8791;color:#fff}.proses-item.current .proses-icon{background:var(--gold);color:#fff}.proses-item.current .proses-body b{color:var(--gold)}.proses-item.rejected .proses-icon{background:#c94d5f;color:#fff}.proses-item.rejected .proses-body b{color:#c94d5f}@media(max-width:700px){.timeline-card{padding:22px}.proses-timeline{align-items:stretch;flex-direction:column;overflow:visible}.proses-item{display:grid;grid-template-columns:52px 1fr;min-width:0;padding:10px 0;text-align:left}.proses-item:before{top:-50%;left:21px;width:2px;height:100%}.proses-icon{margin:0}.proses-body{align-self:center}}
@media(max-width:900px){.document-groups,.review-grid,.tpa-grid,.consultation-fields{grid-template-columns:1fr}.doc-list li{grid-template-columns:34px 1fr}.doc-list em{grid-column:2}}
</style>
<script>
document.querySelectorAll('.document-review-select').forEach(function(select){select.addEventListener('change',function(){if(select.value){select.setAttribute('aria-busy','true');select.form.submit();}});});
document.querySelectorAll('.note-toggle').forEach(function(button){button.addEventListener('click',function(){var panel=button.closest('.stage-card').querySelector('.note-panel');if(panel)panel.hidden=!panel.hidden;});});
document.querySelectorAll('.quick-upload-input').forEach(function(input){input.addEventListener('change',function(){if(!input.files||!input.files.length)return;var trigger=input.closest('.quick-upload-trigger');if(trigger){trigger.classList.add('uploading');trigger.querySelector('span').textContent='Mengunggah…';}input.form.submit();});});
(function(){var modal=document.getElementById('fileModal'),body=document.getElementById('fileModalBody'),title=document.getElementById('fileModalTitle'),open=document.getElementById('fileModalOpen');if(!modal)return;function close(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');body.innerHTML='';}document.querySelectorAll('.view-file').forEach(function(button){button.addEventListener('click',function(){var url=button.dataset.fileUrl,name=button.dataset.fileTitle||'Pratinjau Berkas',ext=(url.split('.').pop()||'').toLowerCase().split('?')[0];title.textContent=name;open.href=url;if(['jpg','jpeg','png','gif','webp'].indexOf(ext)>-1)body.innerHTML='<img src="'+url+'" alt="Pratinjau berkas">';else if(ext==='pdf')body.innerHTML='<iframe src="'+url+'" title="Pratinjau berkas"></iframe>';else body.innerHTML='<p>Berkas tidak dapat dipratinjau. Gunakan tombol Buka di Tab Baru.</p>';modal.classList.add('open');modal.setAttribute('aria-hidden','false');});});modal.querySelectorAll('[data-modal-close]').forEach(function(el){el.addEventListener('click',close);});document.addEventListener('keydown',function(e){if(e.key==='Escape')close();});})();
</script>
